 final MainActivity a; LinearLayout host,output,listPane,area,top; TextView status,radioStatus;
 VideoView video; WebView web; int generation,session,ratioIndex=0,remoteOffset; Channel current; boolean requested=false,radioMode=false,full=false,showList=true,remoteBusy=false,favoritesOnly=false;
 String country="España",category="Todos",query="",remoteCode=""; ArrayAdapter<String> adapter; ListView list; Button favBtn,countryBtn,categoryBtn,listBtn,moreBtn; EditText search;
