 static final class Channel { final String country,cat,name,stream,web,info; final boolean radio; Channel(String[] x,boolean r){country=x[0];cat=x[1];name=x[2];stream=x[3];web=x[4];info=x[5];radio=r;} String key(){return (radio?"R|":"T|")+country+"|"+cat+"|"+name+"|"+stream;} JSONArray json(){return new JSONArray(Arrays.asList(country,cat,name,stream,web,info));} }
 final ArrayList<Channel> tvs=new ArrayList<>(),radios=new ArrayList<>(),remote=new ArrayList<>(),filtered=new ArrayList<>();
 final LinkedHashMap<String,Channel> favorites=new LinkedHashMap<>();
 MediaCenter(MainActivity a){this.a=a;load("tv-catalog.tsv",tvs,false);load("radio-catalog.tsv",radios,true);ratioIndex=Math.max(0,Math.min(3,a.prefs.getInt("media_ratio",0)));try{JSONArray all=new JSONArray(a.prefs.getString("media_favorites_v2","[]"));for(int i=0;i<all.length();i++){JSONObject o=all.getJSONObject(i);JSONArray v=o.getJSONArray("v");String[] x=new String[6];for(int n=0;n<6;n++)x[n]=v.getString(n);Channel c=new Channel(x,o.optBoolean("r"));favorites.put(c.key(),c);}}catch(Exception ignored){}}
 void load(String asset,ArrayList<Channel> dest,boolean r){try(BufferedReader reader=new BufferedReader(new InputStreamReader(a.getAssets().open(asset),StandardCharsets.UTF_8))){String s;while((s=reader.readLine())!=null){String[] x=s.split("\\t",-1);if(x.length==6)dest.add(new Channel(x,r));}}catch(IOException e){android.util.Log.e("CockpitMedia","Catalog",e);}}
 boolean busy(){return video!=null||web!=null;}
