 void toggleFavorite(Channel c){if(c==null){message("Selecciona un canal o emisora");return;}if(favorites.containsKey(c.key()))favorites.remove(c.key());else favorites.put(c.key(),c);save();filter();message(favorites.containsKey(c.key())?"★ Guardado: "+c.name:"Eliminado: "+c.name);}
 Button compact(String text,Runnable click){Button b=a.button(text,click);b.setTextSize(12);b.setMinHeight(a.dp(36));b.setMinimumHeight(a.dp(36));b.setPadding(a.dp(9),0,a.dp(9),0);return b;}
